function mfilterSaveToLocal() {
            try { localStorage.setItem(MFILTER_STORE_KEY, JSON.stringify(mfilterState)); }
            catch (e) { /* ignore */ }
        }

function mfilterBuildSavePayload() {
            return {
                method: MFILTER_METHOD_SAVE,
                source: JSON.stringify(mfilterState.source || []),
                center: JSON.stringify(mfilterState.center || []),
                status: JSON.stringify(mfilterState.status || []),
                priority: JSON.stringify(mfilterState.priority || []),
                disease: JSON.stringify(mfilterState.disease || [])
            };
        }

function mfilterSave() {
            mfilterSaveToLocal();  // optimistic local write — always instant
            mfilterPendingSave = true;
            if (mfilterSaveTimer) clearTimeout(mfilterSaveTimer);
            mfilterSaveTimer = setTimeout(function () {
                mfilterFlushSave();
            }, 500);
        }

function mfilterFlushSave() {
            if (mfilterSaveTimer) { clearTimeout(mfilterSaveTimer); mfilterSaveTimer = null; }
            if (!mfilterPendingSave) return;
            mfilterPendingSave = false;
            $.ajax({
                type: 'POST',
                url: MFILTER_ENDPOINT,
                data: mfilterBuildSavePayload(),
                dataType: 'json',
                success: function (res) {
                    if (!res || !res.ok) {
                        console.warn('[mfilter] Server rejected save:', res);
                    } else if (window.console) {
                        console.log('[mfilter] Saved', res.mode || 'ok');
                    }
                },
                error: function (xhr) {
                    console.error('[mfilter] Save failed:', xhr.status, xhr.responseText);
                    // localStorage already has the state as fallback
                }
            });
        }

function saveReferral(forceInsert) {

            if (!validateReferralForm()) return;

            var rowId = $('#hdnEditRowId').val();

            const date = $('#txtFollowUpDate').val();
            const time = $('#ddlTime').val();
            let followUp = null;

            if (date) {
                followUp = date + " " + (time || "00:00");
                const selected = new Date(followUp);
                const now = new Date();
                const max = new Date();
                max.setFullYear(now.getFullYear() + 1);
                if (selected < now || selected > max) {
                    alert("Follow-up date/time must be within future 1 year");
                    return;
                }
            }

            var teamMemberId = null;

            if ($('#hdnmagent').val()) {
                teamMemberId = parseInt($('#hdnmagent').val());
            }
            else if ($('#hdnTeamMember').val()) {
                teamMemberId = parseInt($('#hdnTeamMember').val());
            }
            var data = {
                RowId: rowId ? parseInt(rowId) : 0,
                PatientName: $('#<%= txtPatientName.ClientID %>').val(),
                Gender: toIntOrNull($('input[name$="rblGender"]:checked').val()),
                Age: toIntOrNull($('#<%= txtAge.ClientID %>').val()),
                Mobile: normalizeMobile($('#txtMob').val()),
                AlternateMobile: normalizeMobile($('#txtAltrnatemob').val()),
                FollowUpDate: followUp,
                Address: $('#<%= txtAddress.ClientID %>').val(),
                Area: toIntOrNull($('#hdnArea').val()),
                AreaName: $('#txtArea').val(),
                Pincode: toIntOrNull($('#hdnpincode').val()),
                City: toIntOrNull($('#hdncity').val()),
                State: toIntOrNull($('#hdnstate').val()),
                Country: toIntOrNull($('#hdncountry').val()),
                CityName: $('#txtcity').val(),
                StateName: $('#txtstate').val(),
                CountryName: $('#txtcountry').val(),
                PatientStatus: toIntOrNull($('#ddlPatientStatus').val()),
                Disease: toIntOrNull($('#ddldisease').val()),
                TeamMemberId: teamMemberId,
                ReferralSourceId: toIntOrNull($('#DdlReferralSource').val()),
                ReferralDoctorId: toIntOrNull($('#hdnRefferalDoctor').val()),
                PracticeId: toIntOrNull($('#<%= ddlPractice.ClientID %>').val()),
                ReferralNote: $('#<%= txtReferralNote.ClientID %>').val(),
                ForceInsert: forceInsert === true
            };

            var formData = new FormData();
            formData.append("model", JSON.stringify(data));
            if (selectedFiles.length > 0) {
                selectedFiles.forEach(function (file) { formData.append("documents", file); });
            }

            $.ajax({
                type: "POST",
                url: '<%= ResolveUrl("~/GenericHandlers/DoctorReferralEntry.ashx") %>',
                data: formData,
                contentType: false,
                processData: false,
                success: function (res) {
                    var result = typeof res === "string" ? JSON.parse(res) : res;
                    if (!result) { alert("Invalid server response"); return; }

                    if (result.confirmRequired) {
                        if (confirm(result.message)) {
                            saveReferral(true);
                        }
                        return;
                    }

                    if (result.ok === true) {
                        var msg = data.RowId > 0 ? 'Referral updated successfully!' : 'Referral saved successfully!';
                        $('#toastMsg').text(msg).fadeIn();
                        setTimeout(function () { $('#toastMsg').fadeOut(); }, 5000);
                        clearReferralForm();
                        $('#hdnEditRowId').val('');
                        GetDoctorReferralRecords();
                    } else {
                        // Prefer backend 'message' (used for business validation like duplicate mobile),
                        // fallback to 'error' (exceptions) or a generic message.
                        alert(result.message || result.error || "Server returned an error");
                    }
                },
                error: function (xhr) {
                    if (xhr.responseText) alert(xhr.responseText);
                    else alert("Server error occurred while saving referral.");
                }
            });
        }

function validateReferralForm() {
            var errors = [];
            if (!$('#<%= txtPatientName.ClientID %>').val().trim())
                errors.push('Patient Name is required');
            if (!toIntOrNull($('input[name$="rblGender"]:checked').val()))
                errors.push('Gender is required');
            var age = toIntOrNull($('#<%= txtAge.ClientID %>').val());
            if (age !== null && (age < 0 || age > 120))
                errors.push('Age must be between 0 and 120');
            if (!toIntOrNull($('#ddldisease').val()))
                errors.push('Disease is required');
            var src = toIntOrNull($('#DdlReferralSource').val());
            if (!src) errors.push('Referral Source is required');
            var DOCTOR_SOURCE_ID = 1;
            if (src === DOCTOR_SOURCE_ID && !toIntOrNull($('#hdnRefferalDoctor').val()))
                errors.push('Referral Doctor is required');
            if (errors.length) { alert(errors.join("\n")); return false; }
            return true;
        }

function isValidDateFormat(dateStr) {
            if (!dateStr) return true;
            var regex = /^\d{4}-\d{2}-\d{2}$/;
            if (!regex.test(dateStr)) return false;
            var date = new Date(dateStr);
            return !isNaN(date.getTime());
        }

function validateDateRange() {
            var from = $('#fromDate').val();
            var to = $('#toDate').val();
            if (!isValidDateFormat(from)) { alert("Invalid From Date format"); $('#fromDate').focus(); return false; }
            if (!isValidDateFormat(to)) { alert("Invalid To Date format"); $('#toDate').focus(); return false; }
            if (from && to) {
                if (new Date(from) > new Date(to)) { alert("From Date cannot be greater than To Date"); return false; }
            }
            var fuFrom = $('#followUpFromDate').val();
            var fuTo = $('#followUpToDate').val();
            if (!isValidDateFormat(fuFrom)) { alert("Invalid Follow-up From Date"); $('#followUpFromDate').focus(); return false; }
            if (!isValidDateFormat(fuTo)) { alert("Invalid Follow-up To Date"); $('#followUpToDate').focus(); return false; }
            if (fuFrom && fuTo && new Date(fuFrom) > new Date(fuTo)) {
                alert("Follow-up From Date cannot be greater than Follow-up To Date");
                return false;
            }
            return true;
        }

function saveNewArea() {
            var countryId = $('#newAreaCountry').val();
            var countryName = $('#newAreaCountry option:selected').text();
            var stateId = $('#newAreaStateId').val();
            var stateName = $('#newAreaState').val().trim();
            var cityName = $('#newAreaCity').val().trim();
            var areaName = $('#newAreaName').val().trim();
            var zipcode = $('#newAreaZipcode').val().trim();
            if (countryId === '0' || !countryId) { $('#newAreaMsg').text('Country is required'); return; }
            if (!stateId) { $('#newAreaMsg').text('State is required'); return; }
            if (!cityName) { $('#newAreaMsg').text('City is required'); return; }
            if (!areaName) { $('#newAreaMsg').text('Area name is required'); return; }
            $('#newAreaMsg').text('');
            $.ajax({
                type: 'POST',
                contentType: 'application/json; charset=utf-8',
                url: 'DoctorReferralEntry.aspx/SaveArea',
                data: JSON.stringify({
                    area_name: areaName, zipcode: zipcode, city_name: cityName,
                    state_id: parseInt(stateId), state_name: stateName,
                    country_id: parseInt(countryId), country_name: countryName
                }),
                dataType: 'json',
                success: function (res) {
                    var result = JSON.parse(res.d);
                    if (result.ok) {
                        $('#newAreaMsg').css('color', '#059669').text('Area added successfully!');
                        setTimeout(function () {
                            closeAddAreaModal();
                            $('#txtArea').val(result.area_name);
                            $('#hdnArea').val(result.area_id);
                            $('#txtpincode').val(result.zipcode);
                            $('#hdnpincode').val(result.zipcode);
                            $('#areaNotFoundMsg').hide();
                            OnSelectOrChange('pincode');
                        }, 2000);
                    } else {
                        $('#newAreaMsg').css('color', '#dc2626').text(result.error || 'Error saving area');
                    }
                },
                error: function (xhr) { $('#newAreaMsg').text('Server error: ' + xhr.responseText); }
            });
        }

saveModalDocuments = function () {
                var status = document.getElementById('kmedUploadStatus');
                if (!modalFiles.length) { status.textContent = 'Please select at least one document.'; status.style.display = 'block'; return; }
                for (var i = 0; i < modalFiles.length; i++) { if (!modalFiles[i].date) { status.textContent = 'Please select Test Done On for ' + modalFiles[i].file.name + '.'; status.style.display = 'block'; return; } }
                var form = new FormData(); form.append('method', 'savePendingDocuments'); form.append('ownerType', uploadOwnerType); form.append('ownerId', String(uploadOwnerId));
                modalFiles.forEach(function (item, i) { form.append('files', item.file, item.file.name); form.append('documentTypeId_' + i, item.typeId || ''); form.append('testDate_' + i, item.date || ''); form.append('note_' + i, item.note || ''); });
                var btn = document.getElementById('kmedSaveDocumentsButton'); btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving...'; status.style.display = 'none';
                $.ajax({
                    url: uploadEndpoint, type: 'POST', data: form, processData: false, contentType: false, dataType: 'json', success: function (r) {
                        if (r && r.saved > 0) {
                            var savedNames = r.savedFiles || [];
                            modalFiles = modalFiles.filter(function (item) { return savedNames.indexOf(item.file.name) < 0; });
                            if (r.success) {
                                var successBox = document.getElementById('kmedUploadSuccess');
                                successBox.textContent = r.saved + ' document(s) saved successfully!';
                                successBox.style.display = 'block';
                                modalFiles = [];
                                renderModalFiles();
                            }
                            else { renderModalFiles(); status.textContent = r.message || ('Saved ' + r.saved + ' document(s); please retry the remaining files.'); status.style.display = 'block'; }
                        } else { status.textContent = (r && r.message) || 'Unable to save documents. Please try again.'; status.style.display = 'block'; }
                    }, error: function (xhr) { status.textContent = 'Upload failed. Please check the file size and try again.'; status.style.display = 'block'; }, complete: function () { btn.disabled = false; btn.innerHTML = '<i class="fa fa-cloud-upload-alt"></i> Save Document'; }
                });
            }
